from typing import List, Optional

class LangfordSolver:
    def __init__(self, n: int = 15):
        self.n = n
        self.length = 2 * n
        self.seq: List[int] = [0] * self.length
        self.used = [False] * (n + 1)
        self.fixed = {3:2, 11:14, 13:11, 26:14, 27:7, 28:10}
        # Add the implied mates
        self.implied = {}
        for pos, val in self.fixed.items():
            dist = val + 1
            other1 = pos + dist
            other2 = pos - dist
            other = None
            if 0 <= other1 < self.length and self.seq[other1] == 0:
                other = other1
            elif 0 <= other2 < self.length and self.seq[other2] == 0:
                other = other2
            if other is not None:
                if other in self.fixed and self.fixed[other] != val:
                    print("Conflict in fixed")
                self.implied[other] = val
        self.fixed.update(self.implied)
        print("All fixed:", self.fixed)

    def is_valid_placement(self, pos: int, val: int) -> bool:
        if self.seq[pos] != 0:
            return False
        other = pos + val + 1
        if other >= self.length or self.seq[other] != 0:
            return False
        return True

    def place(self, pos: int, val: int):
        self.seq[pos] = val
        self.seq[pos + val + 1] = val
        self.used[val] = True

    def remove(self, pos: int, val: int):
        self.seq[pos] = 0
        self.seq[pos + val + 1] = 0
        self.used[val] = False

    def solve(self) -> bool:
        # First apply fixed
        for pos in sorted(self.fixed.keys()):
            val = self.fixed[pos]
            if self.seq[pos] != 0:
                continue  # already placed as mate
            if not self.is_valid_placement(pos, val):
                return False
            self.place(pos, val)
            self.used[val] = True  # already set but ok
        # Now backtrack on remaining
        return self.backtrack(0)

    def backtrack(self, start: int) -> bool:
        # Find next empty position
        pos = -1
        for i in range(start, self.length):
            if self.seq[i] == 0:
                pos = i
                break
        if pos == -1:
            return True  # all filled

        for val in range(self.n, 0, -1):  # largest first
            if not self.used[val]:
                if self.is_valid_placement(pos, val):
                    self.place(pos, val)
                    if self.backtrack(pos + 1):
                        return True
                    self.remove(pos, val)
        return False

    def get_solution(self) -> Optional[List[int]]:
        if self.solve():
            return self.seq[:]
        return None

